/*
 * sme_rc5_bench: does Arm SME (streaming SVE) check RC5-72 keys faster than NEON?
 *
 * A probe, not part of the distributed.net client. It does no distributed.net
 * work: it encrypts with made-up keys and only measures speed.
 *
 * Build and run (macOS on Apple silicon, or Linux on arm64):
 *
 *     cc -O2 -o sme_rc5_bench sme_rc5_bench.c -lpthread
 *     ./sme_rc5_bench
 *
 * It takes about 30 seconds. Optional argument: seconds per measurement
 * (default 1.0), for example "./sme_rc5_bench 0.2" for a quick run.
 * The word "force" as an argument checks the SVE kernels even when a probe
 * failed (for testing the fault reports).
 *
 * What it does, in order, printing as it goes:
 *   1. system information (which SME features the system reports);
 *   2. a self-check of the plain C RC5-72 against distributed.net test keys;
 *   3. probes: each kind of instruction the SME kernels need is tried once,
 *      and an illegal instruction is reported instead of crashing;
 *   4. every kernel is checked against the plain C version;
 *   5. every kernel that passed is timed on one thread;
 *   6. the best NEON and best SME kernels are timed on several threads.
 *
 * The SME / SVE kernels are machine code generated by gen_kernels.py (the
 * readable assembly is kernels.S) and embedded below as .long words, so no
 * assembler support for SME is needed to build this file.
 */

#if !defined(__aarch64__)
#error "This program is for 64-bit Arm (arm64 / aarch64) only."
#endif

#define _GNU_SOURCE
#include <pthread.h>
#include <setjmp.h>
#include <signal.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <arm_neon.h>
#if defined(__APPLE__)
#include <sys/sysctl.h>
#include <pthread/qos.h>
#else
#include <sys/auxv.h>
#include <ucontext.h>
#endif

#define BENCH_VERSION "2"

#define P 0xB7E15163u
#define Q 0x9E3779B9u

/* ---- kernel interface --------------------------------------------------- */

/* A kernel checks nbatch batches of keys. Key number idx (0, 1, 2, ...) uses
   t = hi0 + idx, L2 = t & 0xff, L1 = l1 + (t >> 8), L0 = l0, and its two
   encrypted words go to out_a[idx] and out_b[idx]. */
typedef struct
{
  uint32_t l0, l1, hi0, nbatch;
  uint32_t plain_lo, plain_hi, pad0, pad1;
  uint32_t *out_a, *out_b;
  uint32_t *scratch;         /* 26 * streams vectors, for the SVE kernels */
  const uint32_t *consts;    /* P + i*Q, i = 0..25 */
} kargs_t;

_Static_assert(offsetof(kargs_t, hi0) == 8 && offsetof(kargs_t, plain_lo) == 16 &&
               offsetof(kargs_t, out_a) == 32 && offsetof(kargs_t, scratch) == 48 &&
               offsetof(kargs_t, consts) == 56, "kargs_t layout (see gen_kernels.py)");

static uint32_t ks_consts[26];

/* ---- embedded machine code ---------------------------------------------- */

#if defined(__APPLE__)
#define SYM(n) "_" #n
#else
#define SYM(n) #n
#endif
#define BLOB_BEGIN(n) \
  extern void n(void); \
  __asm__(".text\n.p2align 2\n.globl " SYM(n) "\n" SYM(n) ":\n"
#define BLOB_END(n, size) ); enum { n##_size = size };

